import {
  CaretRightOutlined,
  DownloadOutlined,
  ExportOutlined,
  GithubOutlined,
  RightOutlined,
} from '@ant-design/icons';
import { useEffect, useState } from 'react';
import { useQuery } from 'react-query';
import { useMediaQuery } from 'react-responsive';
import { Link } from 'react-router-dom';
import { databaseURL } from '../app.constants';
import CardsPreviewContainer from '../component/CardsPreviewContainer';
import ContentWrapper from '../component/ContentWrapper';
import Hero from '../component/Hero';
import ResponsiveGridWrapper from '../component/ResponsiveGridWrapper';
import { callAPI } from '../config/api';
import {
  BlenderRenderResponseType,
  GameResponseType,
} from '../config/api/responseTypes';
import { WEB_APP_PROJECTS } from '../dummyData/web-app-projects';
import { cn } from '../utils/utils';

export default function Homepage() {
  const isDesktopOrLaptop = useMediaQuery({
    query: '(min-width: 40rem)',
  });
  const [latestPosts, setLatestPosts] = useState<any[]>([]);
  const { data: renders } = useQuery('renders', fetchRenders);

  async function fetchBlogs() {
    const data = await callAPI<any[]>({
      url: databaseURL('database', 'blog/data.json'),
      method: 'GET',
    });
    setLatestPosts(data.slice(0, 5));
  }
  async function fetchRenders() {
    return await callAPI<BlenderRenderResponseType[]>({
      url: databaseURL('database', 'creation/blender/render/data.json'),
      method: 'GET',
    });
  }
  const { data: games } = useQuery('games', fetchGames);

  async function fetchGames() {
    return await callAPI<GameResponseType[]>({
      url: databaseURL('database', 'creation/game/data.json'),
      method: 'GET',
    });
  }

  useEffect(() => {
    window.scrollTo({
      top: 0,
    });
  }, []);

  useEffect(() => {
    fetchBlogs();
  }, []);
  return (
    <div>
      <Hero />
      <div className="mt-64 flex flex-col items-center">
        <h2 className="text-2xl">My Latest</h2>
        <h1 className="text-6xl">Projects</h1>
        {/* <p className="w-96 mt-6">
          Lorem, ipsum dolor sit amet consectetur adipisicing elit. Ullam
          mollitia quibusdam autem labore iste doloremque distinctio at maxime
          voluptatibus debitis?
        </p> */}
        <div
          className={cn(
            'flex gap-3 h-96 w-full  mt-6 overflow-x-auto',
            isDesktopOrLaptop ? 'justify-center' : '',
          )}
        >
          {WEB_APP_PROJECTS.map((project) => (
            <div
              className="aspect-[9/14] h-full rounded-2xl bg-black bg-cover bg-top relative text-white"
              style={{
                backgroundImage: `url("${project.thumbnail}")`,
              }}
            >
              <div className="w-full h-full bg-[rgba(0,0,0,.6)] absolute isolate z-[0] rounded-2xl" />
              <div className="flex flex-col text-left p-5 h-full">
                <h4 className="text-xl font-bold z-[1] mb-2">{project.name}</h4>
                <p className="z-[1] text-sm text-gray-300">
                  {project.description}
                </p>
                <div className="z-10 h-12 mt-auto flex gap-1 items-end">
                  {project.tags.map((tag) => (
                    <button
                      className="bg-[rgba(255,255,255,.5)] rounded-full px-3 text-sm h-[50%] text-black"
                      disabled
                    >
                      {tag}
                    </button>
                  ))}
                  {project.href && (
                    <a
                      className="h-full aspect-square ml-auto border-gray-300 text-gray-300 border-[1px] rounded-md text-xl flex justify-center items-center"
                      href={project.href}
                      target="_blank"
                    >
                      <RightOutlined />
                    </a>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="mt-32 flex flex-col items-center">
        <h2 className="text-5xl">Games</h2>
        {/* <p className="w-96 mt-6">
          Lorem, ipsum dolor sit amet consectetur adipisicing elit. Ullam
          mollitia quibusdam autem labore iste doloremque distinctio at maxime
          voluptatibus debitis?
        </p> */}
        <div className="flex gap-3 h-96 w-full justify-center mt-6 ">
          <div
            className="aspect-[16/9] h-full rounded-2xl bg-black bg-cover bg-center flex justify-center items-center"
            style={{}}
          >
            <h2 className="text-5xl text-gray-400">Coming Soon</h2>
          </div>
          {games && (
            <div
              className="aspect-[16/9] h-full w-auto rounded-2xl bg-black bg-cover bg-center relative"
              style={{
                backgroundImage: `url("${games[0].backgroundUrl}")`,
              }}
            >
              <div className="w-full h-full flex flex-col items-center text-gray-400 bg-[rgba(0,0,0,.7)] absolute isolate z-[0] rounded-2xl p-4">
                <div
                  className="aspect-[3] w-[50%] rounded-2xl bg-cover bg-center"
                  style={{
                    backgroundImage: `url("${games[0].gameLogoUrl}")`,
                  }}
                ></div>
                <p>{games[0].description}</p>
                <div className="mt-auto flex flex-col items-center">
                  <a
                    href={games[0].playUrl}
                    target="_blank"
                    className="bg-white rounded-full px-5 py-3 text-black  text-lg flex justify-between items-center gap-3 "
                  >
                    PLAY ON BROWSER
                    <CaretRightOutlined />
                  </a>
                  <div className="flex mt-1 gap-1 w-[80%]">
                    <a
                      href={games[0].downloadUrl}
                      className=" px-2 py-1 text-gray-300 w-full text-xs flex justify-between items-center gap-3 "
                    >
                      Download
                      <DownloadOutlined />
                    </a>
                    <a
                      href={games[0].repositoryUrl}
                      target="_blank"
                      className=" px-2 py-1 text-gray-300 w-full text-xs flex justify-between items-center gap-3 "
                    >
                      Repository
                      <GithubOutlined />
                    </a>
                  </div>
                </div>
              </div>
            </div>
          )}
          <div
            className="aspect-[16/9] h-full rounded-2xl bg-black bg-cover bg-center flex justify-center items-center"
            style={{}}
          >
            <h2 className="text-5xl text-gray-400">Coming Soon</h2>
          </div>
        </div>
      </div>
      <div className="mt-32 flex flex-col items-center">
        <h2 className="text-5xl">3D Arts</h2>
        {/* <p className="w-96 mt-6">
          Lorem, ipsum dolor sit amet consectetur adipisicing elit. Ullam
          mollitia quibusdam autem labore iste doloremque distinctio at maxime
          voluptatibus debitis?
        </p> */}
        <div className="gap-3 h-auto w-full justify-center mt-6">
          <ContentWrapper noPadding>
            <ResponsiveGridWrapper minSize="20rem">
              {renders &&
                renders.slice(0, 6).map((render) => (
                  <div
                    className="aspect-[16/9] w-full rounded-2xl bg-black bg-cover bg-center"
                    style={{
                      backgroundImage: `url(${render.image.compressed})`,
                    }}
                  ></div>
                ))}
            </ResponsiveGridWrapper>
          </ContentWrapper>
        </div>
      </div>
      <div className="mt-32 flex flex-col items-center">
        <h2 className="text-5xl">More?</h2>
        {/* <p className="w-96 mt-6">
          Lorem, ipsum dolor sit amet consectetur adipisicing elit.
        </p> */}
        <ContentWrapper noPadding>
          <div
            className={cn(
              'grid w-full auto-cols-auto auto-rows-auto gap-1 mt-6',
              isDesktopOrLaptop ? 'aspect-[2]' : 'aspect-square',
            )}
            style={{
              gridTemplateAreas: `
            "💎 💎 💖"
            "🌟 ✨ 💖"
            "🌟 ❇️ ❇️"
            `,
            }}
          >
            {renders && (
              <>
                <Link
                  to={'creation'}
                  style={{
                    gridArea: '✨',
                  }}
                  className="bg-black rounded-2xl bg-center bg-cover flex justify-center items-center cursor-pointer"
                >
                  <h1
                    className={cn(
                      isDesktopOrLaptop ? 'text-7xl' : 'text-4xl',
                      ' text-white',
                    )}
                  >
                    <ExportOutlined />
                  </h1>
                </Link>
                <div
                  style={{
                    gridArea: '💎',
                    backgroundImage: `url("${renders[1].image.compressed}")`,
                  }}
                  className="bg-black rounded-2xl bg-center bg-cover flex justify-center items-center relative overflow-hidden text-white"
                >
                  <div className="w-full h-full bg-[rgba(0,0,0,.5)] absolute isolate z-0" />
                  <h1
                    className={cn(
                      isDesktopOrLaptop ? 'text-7xl' : 'text-3xl',
                      'z-10',
                    )}
                  >
                    Browse
                  </h1>
                </div>

                <div
                  style={{
                    gridArea: '💖',
                    backgroundImage: `url("${renders[14].image.compressed}")`,
                  }}
                  className="bg-black rounded-2xl bg-center bg-cover flex justify-center items-center relative overflow-hidden text-white"
                >
                  <div className="w-full h-full bg-[rgba(0,0,0,.5)] absolute isolate z-0" />
                  <h1
                    className={cn(
                      isDesktopOrLaptop ? 'text-7xl' : 'text-3xl',
                      'z-10',
                    )}
                  >
                    All
                  </h1>
                </div>
                <div
                  style={{
                    gridArea: '🌟',
                    backgroundImage: `url("${renders[6].image.compressed}")`,
                  }}
                  className="bg-black rounded-2xl bg-center bg-cover flex justify-center items-center relative overflow-hidden text-white"
                >
                  <div className="w-full h-full bg-[rgba(0,0,0,.5)] absolute isolate z-0" />
                  <h1
                    className={cn(
                      isDesktopOrLaptop ? 'text-7xl' : 'text-3xl',
                      'z-10',
                    )}
                  >
                    My
                  </h1>
                </div>
                <div
                  style={{
                    gridArea: '❇️',
                    backgroundImage: `url("${renders[3].image.compressed}")`,
                  }}
                  className="bg-black rounded-2xl bg-center bg-cover flex justify-center items-center relative overflow-hidden text-white"
                >
                  <div className="w-full h-full bg-[rgba(0,0,0,.5)] absolute isolate z-0" />
                  <h1
                    className={cn(
                      isDesktopOrLaptop ? 'text-7xl' : 'text-3xl',
                      'z-10',
                    )}
                  >
                    Creations
                  </h1>
                </div>
              </>
            )}
          </div>
          {/* <CardsPreviewContainer
            style={{ marginTop: 100 }}
            items={latestPosts}
          /> */}
        </ContentWrapper>
      </div>
    </div>
  );
}
