import { SendOutlined } from '@ant-design/icons';
import { Button, Flex, Typography } from 'antd';
import { Link } from 'react-router-dom';
import { socialMedias } from '../app.constants';
import ContentWrapper from '../component/ContentWrapper';

export default function ContactPage() {
  return (
    <ContentWrapper contentGap={50}>
      <Typography.Title level={1} className="text-left">
        Contact Us!
      </Typography.Title>
      <Flex vertical align="flex-start">
        <Typography.Title level={4}>Business Inquiry</Typography.Title>
        <Typography.Paragraph>
          If you have any business inquiries or requests, click the button below
          to send us an email. We'll get back to you as soon as possible!
        </Typography.Paragraph>
        <span className="my-3">febryanshinos@gmail.com</span>
        <Link
          to={
            'https://mail.google.com/mail/?view=cm&fs=1&to=febryanshinos@gmail.com&su=Business%20Inquiry'
          }
          target="_blank"
        >
          <Button
            icon={<SendOutlined />}
            iconPosition="end"
            size="large"
            type="default"
            variant="outlined"
            className="bg-transparent"
          >
            Send Email
          </Button>
        </Link>
      </Flex>
      <Flex vertical align="flex-start" className="w-full">
        <Typography.Title level={4}>My Social Media</Typography.Title>

        <Flex wrap gap={5}>
          {socialMedias('DARK').map((social) => (
            <Button size="large" icon={social.icon}>
              {social.username}
            </Button>
          ))}
        </Flex>
      </Flex>
    </ContentWrapper>
  );
}
