import { PhoneOutlined, SmileOutlined } from '@ant-design/icons';
import {
  faJsSquare,
  faLaravel,
  faNodeJs,
  faPhp,
  faPython,
  faReact,
} from '@fortawesome/free-brands-svg-icons';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { useGSAP } from '@gsap/react';
import { Flex, Typography } from 'antd';
import gsap from 'gsap';
import { useRef } from 'react';
import { useMediaQuery } from 'react-responsive';
import { Link } from 'react-router-dom';
import { databaseURL } from '../app.constants';
import { cn } from '../utils/utils';
import ResponsiveGridWrapper from './ResponsiveGridWrapper';

const { Paragraph } = Typography;

const SPECIALTIES = [
  {
    name: 'React',
    icon: faReact,
  },
  {
    name: 'JavaScript',
    icon: faJsSquare,
  },
  {
    name: 'Node.js',
    icon: faNodeJs,
  },
  {
    name: 'Laravel',
    icon: faLaravel,
  },
  {
    name: 'Python',
    icon: faPython,
  },
  {
    name: 'PHP',
    icon: faPhp,
  },
];

export default function Hero() {
  const isDesktopOrLaptop = useMediaQuery({
    query: '(min-width: 40rem)',
  });

  const container = useRef(null);

  useGSAP(
    () => {
      gsap.fromTo(
        container.current,
        {
          backgroundSize: '100px',
          backgroundPositionX: -100,
          backgroundPositionY: 50,
        },
        {
          backgroundSize: (100 * 20) / 9 + '%',
          backgroundPosition: 50,
          duration: 3,
        },
      );
    },
    { scope: container },
  );
  return (
    <div
      className={cn(
        'flex ',
        isDesktopOrLaptop ? 'flex-row' : 'flex-col-reverse',
      )}
      style={{
        width: '100%',
        height: '100dvh',
        minHeight: '100dvh',
        backgroundSize: 'cover',
      }}
    >
      <Flex
        className={`${isDesktopOrLaptop ? 'w-[50%] pt-32' : 'w-[100%] pt-4 h-[60%]'}  text-left flex items-center`}
        vertical
        gap={0}
      >
        <div className={cn(isDesktopOrLaptop ? 'px-16' : 'px-4')}>
          <Flex vertical>
            <h1
              className={cn(
                isDesktopOrLaptop ? 'text-6xl' : 'text-5xl mt-4',
                'mb-6',
              )}
            >
              Febryan Shino
            </h1>
          </Flex>
          <Flex
            vertical
            className={isDesktopOrLaptop ? 'max-h-[30dvh]' : 'max-h-[20dvh]'}
            align="end"
            // style={{ border: '.1rem solid black' }}
          >
            <Paragraph className="p-3 h-full  overflow-y-auto">
              I'm a passionate programmer, software engineer and fullstack web
              developer also who loves 3D arts, proud graduate of SMKN 3 Jepara.
              A double LKS Web Technologies champion (Jepara) and recognized
              among the top 10 in Central Java, I bring expertise in React,
              Next.js, Laravel, Node.js, Flask, and Django.
              <br />
              With a TOEIC score of 860, I'm prepared to collaborate effectively
              on global projects. Known for being a fast learner, I'm proactive,
              team-oriented, and capable of delivering results independently—all
              driven by a genuine passion for technology and innovation.
            </Paragraph>
          </Flex>
          <Flex gap={6} className="-mt-3 ml-3 h-12">
            <Link to="/about">
              <button className="w-36 h-full bg-primary text-black border-black border-[.05rem] rounded-none flex gap-3 justify-center items-center">
                About Me
                <SmileOutlined />
              </button>
            </Link>
            <Link to="/contact">
              <button className="w-36 h-full bg-black text-white border-black border-[.05rem] rounded-none flex gap-3 justify-center items-center">
                Contact
                <PhoneOutlined />
              </button>
            </Link>
          </Flex>
          <div className={`aspect-[4] text-black pl-3 mt-9`}>
            <h3 className="text-2xl mb-5">My Specialties</h3>
            <div className="w-full h-auto overflow-y-auto">
              <ResponsiveGridWrapper
                minSize={isDesktopOrLaptop ? '2rem' : '3rem'}
                gap={'2rem'}
              >
                {SPECIALTIES.map((specialty) => (
                  <div className=" w-full aspect-square flex justify-center items-center flex-col">
                    <FontAwesomeIcon
                      icon={specialty.icon}
                      color="white"
                      className={cn(
                        isDesktopOrLaptop ? 'text-4xl' : 'text-4xl',
                        'text-black',
                      )}
                    />
                  </div>
                ))}
              </ResponsiveGridWrapper>
            </div>
          </div>
        </div>
        <Flex className="w-full h-[40%]" align="end">
          <div
            className={cn(
              `h-full aspect-[2] bg-cover bg-center px-5`,
              isDesktopOrLaptop ? 'w-[90%]' : 'w-[100%]',
            )}
            style={
              {
                // backgroundImage: `url(${databaseURL(
                //   'website',
                //   'images/hero.png',
                // )})`,
              }
            }
          ></div>
          {isDesktopOrLaptop && (
            <div
              className={`h-[60%] w-auto aspect-[2] bg-cover bg-center`}
              style={{
                transform: 'translate(-30%, 30%)',
                backgroundImage: `url("${databaseURL(
                  'website',
                  'images/hero.png',
                )}")`,
              }}
            />
          )}
        </Flex>
      </Flex>
      <div
        ref={container}
        className={` ${isDesktopOrLaptop ? 'w-[50%] h-full aspect-square' : 'w-[100%] h-[50%]'}  bg-cover bg-top`}
        style={{
          backgroundImage: `url(${databaseURL('website', 'images/hero.png')})`,
        }}
      />
    </div>
  );
}
