import { useGSAP } from '@gsap/react';
import { Button, Divider, Flex, Space, Typography } from 'antd';
import gsap, { Linear } from 'gsap';
import { useRef } from 'react';
import { useMediaQuery } from 'react-responsive';
import { Link } from 'react-router-dom';
import { socialMedias } from '../app.constants';
import { FOOTER_LINKS } from '../config/footer';
import { cn } from '../utils/utils';
import ContentWrapper from './ContentWrapper';

const { Title } = Typography;

export default function Footer(props: { theme?: 'DARK' | 'LIGHT' }) {
  const isDesktopOrLaptop = useMediaQuery({
    query: '(min-width: 40rem)',
  });
  const container = useRef(null);
  const socialItems = useRef<(HTMLButtonElement | HTMLAnchorElement | null)[]>(
    [],
  );

  const { contextSafe } = useGSAP(
    () => {
      gsap.fromTo(
        socialItems.current,
        {
          yPercent: 200,
        },
        {
          scrollTrigger: {
            trigger: container.current,
          },
          yPercent: 0,
          duration: 0.5,
          stagger: {
            each: 0.1,
          },
        },
      );
      gsap.fromTo(
        socialItems.current,
        {
          opacity: 0,
          delay: 1,
        },
        {
          scrollTrigger: {
            trigger: container.current,
          },
          opacity: 1,
          duration: 0.5,
          stagger: {
            each: 0.1,
          },
        },
      );
    },
    { scope: container },
  );

  const onEnter = contextSafe((target: EventTarget) => {
    const item = gsap.utils.selector(target)('.idk-man');
    gsap.to(item, {
      scale: 1.5,
      duration: 0.3,
      rotate: 360,
      ease: Linear.easeNone,
    });
  });
  const onLeave = contextSafe((target: EventTarget) => {
    const item = gsap.utils.selector(target)('.idk-man');
    gsap.to(item, {
      scale: 1,
      duration: 0.3,
      rotate: 0,
    });
  });

  return (
    <div
      className={cn(
        'bg-black w-full h-auto text-white',
        props.theme === 'DARK' ? 'pt-32' : 'mt-32',
      )}
      ref={container}
    >
      <ContentWrapper>
        <Flex wrap={!isDesktopOrLaptop} gap={!isDesktopOrLaptop ? 80 : 20}>
          <Flex
            className={isDesktopOrLaptop ? 'w-[50%]' : 'w-[100%]'}
            align={isDesktopOrLaptop ? 'flex-start' : 'center'}
            vertical
          >
            <div
              style={{
                height: '100px',
                width: '300px',
                backgroundImage: 'url(/logo.png)',
              }}
              className="bg-cover bg-center"
            ></div>
            <Flex gap={10}>
              {socialMedias('LIGHT').map((item, index) => (
                <a
                  href={item.href}
                  target="_blank"
                  onMouseEnter={({ currentTarget }) => onEnter(currentTarget)}
                  onMouseLeave={({ currentTarget }) => onLeave(currentTarget)}
                >
                  <Button
                    className="idk-man"
                    type="text"
                    icon={item.icon}
                    ref={(el) => (socialItems.current[index] = el)}
                  />
                </a>
              ))}
            </Flex>
          </Flex>
          <Flex gap="4rem" className="w-full" wrap>
            {FOOTER_LINKS.map((link: any, index: number) => (
              <Space direction="vertical" className="text-left">
                <Title style={{ color: 'white' }} level={4}>
                  {link.header}
                </Title>
                {link.items.map((item: any) => (
                  <Link to={item.href}>{item.name}</Link>
                ))}
              </Space>
            ))}
          </Flex>
        </Flex>
      </ContentWrapper>
      <Flex justify="center" align="center" vertical className="pb-10">
        <Divider className="border-white" />
        <Typography.Text className="text-white">
          © {new Date(Date.now()).getFullYear()} FebryanShino
        </Typography.Text>
      </Flex>
    </div>
  );
}
