import { ConfigProvider } from 'antd';
import { QueryClient, QueryClientProvider } from 'react-query';
import { Route, Routes } from 'react-router-dom';
import './App.css';
import MainLayout from './MainLayout';
import AboutMePage from './pages/AboutMePage';
import AndroidAppsDetailPage from './pages/android-apps/AndroidAppsDetailPage';
import AndroidAppsListPage from './pages/android-apps/AndroidAppsListPage';
import AssetDetail from './pages/blender-asset/AssetDetail';
import AssetsSearch from './pages/blender-asset/AssetsSearch';
import RenderDetail from './pages/blender-render/RenderDetail';
import RenderList from './pages/blender-render/RenderList';
import BlenderCreationPage from './pages/BlenderCreationPage';
import CompanyIdeasDetailPage from './pages/company-ideas/CompanyIdeasDetailPage';
import CompanyIdeasListPage from './pages/company-ideas/CompanyIdeasListPage';
import ContactPage from './pages/ContactPage';
import CreationPage from './pages/CreationPage';
import GameCreationPage from './pages/GameCreationPage';
import Homepage from './pages/Homepage';
import NotFound from './pages/NotFound';
import ProgrammingLandingPage from './pages/programming/ProgrammingLandingPage';

const queryClient = new QueryClient();

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <div className="App bg-[hsl(0,0%,95%)] overflow-x-hidden">
        <ConfigProvider
          theme={{
            token: {
              // colorPrimary: '#f2f2f2',
              colorPrimary: '#453f3c',
              fontSize: 16,
              colorTextTertiary: 'black',
              colorTextSecondary: 'black',
              colorFillTertiary: '#453f3c',
              // colorFillSecondary: 'black',
              // colorTextSecondary: 'black',
              // colorBgContainer: '#f2f2f2',
            },
          }}
        >
          <Routes>
            <Route
              path="/"
              element={
                <MainLayout>
                  <Homepage />
                </MainLayout>
              }
            />
            <Route
              path="/creation"
              element={
                <MainLayout>
                  <CreationPage />
                </MainLayout>
              }
            />
            <Route
              path="/contact"
              element={
                <MainLayout>
                  <ContactPage />
                </MainLayout>
              }
            />
            <Route
              path="/about"
              element={
                <MainLayout>
                  <AboutMePage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/blender"
              element={
                <MainLayout theme="DARK">
                  <BlenderCreationPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/blender/assets"
              element={
                <MainLayout>
                  <AssetsSearch />
                </MainLayout>
              }
            />
            <Route
              path="/creation/blender/assets/:id"
              element={
                <MainLayout>
                  <AssetDetail />
                </MainLayout>
              }
            />

            <Route
              path="/creation/blender/render"
              element={
                <MainLayout theme="DARK">
                  <RenderList />
                </MainLayout>
              }
            />
            <Route
              path="/creation/blender/render/:id"
              element={
                <MainLayout>
                  <RenderDetail />
                </MainLayout>
              }
            />

            <Route
              path="/creation/programming"
              element={
                <MainLayout>
                  <ProgrammingLandingPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/game"
              element={
                <MainLayout theme="DARK">
                  <GameCreationPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/company-ideas"
              element={
                <MainLayout>
                  <CompanyIdeasListPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/company-ideas/:id"
              element={
                <MainLayout>
                  <CompanyIdeasDetailPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/android-apps"
              element={
                <MainLayout>
                  <AndroidAppsListPage />
                </MainLayout>
              }
            />
            <Route
              path="/creation/android-apps/:id"
              element={
                <MainLayout>
                  <AndroidAppsDetailPage />
                </MainLayout>
              }
            />
            <Route
              path="*"
              element={
                <MainLayout>
                  <NotFound />
                </MainLayout>
              }
            />
          </Routes>
        </ConfigProvider>
      </div>
    </QueryClientProvider>
  );
}

export default App;
