import { useGSAP } from '@gsap/react';
import { Button, Carousel, Flex, Typography } from 'antd';
import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import ContentWrapper from '../component/ContentWrapper';

import {
  AppstoreOutlined,
  ExportOutlined,
  MoonOutlined,
  SunOutlined,
} from '@ant-design/icons';
import gsap from 'gsap';
import { useQuery } from 'react-query';
import { useMediaQuery } from 'react-responsive';
import { databaseURL } from '../app.constants';
import { callAPI } from '../config/api';
import { BlenderRenderResponseType } from '../config/api/responseTypes';
import { cn } from '../utils/utils';

const { Title } = Typography;
const backgrounds = [
  [
    'https://pbs.twimg.com/media/GD6WGZka8AAFFaZ?format=jpg&name=large',
    'Wireframe',
  ],
  [
    'https://pbs.twimg.com/media/GD6WGZlbcAAyaP6?format=jpg&name=large',
    'Solid',
  ],
  [
    'https://pbs.twimg.com/media/GD6WGZiaUAAG1j0?format=jpg&name=large',
    'Materials',
  ],
  [
    'https://pbs.twimg.com/media/GD6WGZtaUAAsDcb?format=jpg&name=large',
    'EEVEE',
  ],
  [
    'https://pbs.twimg.com/media/GD4fHkBbcAAo2fW?format=jpg&name=large',
    'Cycles',
  ],
];

export default function BlenderCreationPage() {
  const [lightIsTurnedOn, setLightIsTurnedOn] = useState(false);
  const container = useRef(null);
  const rotatingSquare = useRef(null);
  const lightToggleButton = useRef(null);
  const [currentImage, setCurrentImage] = useState(backgrounds[0]);
  const { data: renders } = useQuery('renders', fetchRenders);
  const isDesktopOrLaptop = useMediaQuery({
    query: '(min-width: 40rem)',
  });

  async function fetchRenders() {
    return await callAPI<BlenderRenderResponseType[]>({
      url: databaseURL('database', 'creation/blender/render/data.json'),
      method: 'GET',
    });
  }

  const { contextSafe } = useGSAP({ scope: container });

  const onBeforeSlide = contextSafe(() => {
    gsap.to(rotatingSquare.current, {
      rotate: '+=45',
      duration: 1,
    });
  });

  const lightToggleOnMouseEnter = contextSafe(() => {
    gsap.to(lightToggleButton.current, {
      background: 'radial-gradient(white 100%, transparent 100%)',
      duration: 0.3,
      boxShadow: '0 0 1rem white',
    });
    gsap.to('.toggle-light-text', {
      duration: 0.3,
      color: 'black',
    });
    gsap.to('.blurry-background', {
      duration: 0.3,
      opacity: 0,
    });
  });

  const lightToggleOnMouseLeave = contextSafe(() => {
    gsap.to(lightToggleButton.current, {
      background: 'radial-gradient(white 0%, transparent 0%)',
      duration: 0.3,
      boxShadow: 'none',
    });
    gsap.to('.toggle-light-text', {
      duration: 0.3,
      color: 'white',
    });
    gsap.to('.blurry-background', {
      duration: 0.3,
      opacity: 1,
    });
  });

  useEffect(() => {
    window.scrollTo({
      top: 0,
    });
  }, []);

  return (
    <div ref={container} className="bg-black">
      <div
        className="w-full h-screen bg-cover bg-center flex justify-center flex-col relative"
        style={{
          backgroundImage: `url("${lightIsTurnedOn ? '/light-setup.webp' : '/night-setup.webp'}")`,
          transition: 'background-image .5s ease',
        }}
      >
        <div
          className="w-full h-full absolute isolate -z-1 blurry-background"
          style={{ backdropFilter: 'blur(5px)' }}
        />
        <ContentWrapper>
          <Flex vertical align="center">
            <Typography.Title className={'z-10'}>
              <span className={cn('text-6xl', 'text-white')}>
                Blender Creation
              </span>
            </Typography.Title>

            <button
              ref={lightToggleButton}
              onMouseEnter={() => lightToggleOnMouseEnter()}
              onMouseLeave={() => lightToggleOnMouseLeave()}
              onClick={() => setLightIsTurnedOn(!lightIsTurnedOn)}
              className={cn(
                'text-white',
                'h-[100%] py-5 w-[15rem] rounded-full z-10 border-2 border-white flex items-center gap-5 justify-center',
              )}
              style={{
                background: 'radial-gradient(white 0%, transparent 0%)',
                backgroundSize: '100% 350%',
                backgroundPosition: 'center',
              }}
            >
              <Typography.Text>
                <span className={'text-white toggle-light-text'}>
                  Set to {lightIsTurnedOn ? 'Night' : 'Day'}
                </span>
              </Typography.Text>
              {lightIsTurnedOn ? (
                <MoonOutlined
                  className="toggle-light-text"
                  style={{ fontSize: '1.5rem' }}
                />
              ) : (
                <SunOutlined
                  className="toggle-light-text"
                  style={{ fontSize: '1.5rem' }}
                />
              )}
            </button>
          </Flex>
        </ContentWrapper>
      </div>
      <div
        className="relative p-3 bg-black bg-cover bg-center"
        style={{
          backgroundImage: `url("/library.png")`,
        }}
      >
        <ContentWrapper>
          <Typography.Title style={{ color: 'white' }}>
            Blender Renders
          </Typography.Title>
          <div className="w-full aspect-square b-black relative flex justify-center items-center">
            <div className="absolute inset-0 m-auto w-[70%] aspect-[16/9] z-[2] bg-black">
              {renders && (
                <Carousel
                  beforeChange={(currentSlide, nextSlide) => {
                    setCurrentImage(backgrounds[nextSlide]);
                    onBeforeSlide();
                  }}
                  fade
                  autoplay
                  dots={false}
                  autoplaySpeed={2000}
                >
                  {backgrounds.map((item) => (
                    <img src={item[0]} />
                  ))}
                </Carousel>
              )}
            </div>
            {renders && (
              <>
                <div
                  className="absolute inset-0 my-[65%] w-[50%] aspect-[2] z-[3] bg-black bg-cover bg-center"
                  style={{
                    backgroundImage: `url(${renders[3]?.image.compressed})`,
                  }}
                />
                <div
                  className="absolute inset-0 my-[68%] mx-[75%] w-[20%] aspect-[9/14] z-1 bg-black bg-cover bg-center"
                  style={{
                    backgroundImage: `url(${renders[4]?.image.compressed})`,
                  }}
                />
                <div
                  className="absolute inset-0 my-[13%] mx-[72%] w-[28%] aspect-square z-1 bg-black bg-cover bg-center"
                  style={{
                    backgroundImage: `url(${renders[1]?.image.compressed})`,
                  }}
                />
                <div
                  className="absolute inset-0 my-[10%] mx-[5%] w-[30%] aspect-[10/16] z-[1] bg-black bg-cover bg-center"
                  style={{
                    backgroundImage: `url(${renders[14]?.image.compressed})`,
                  }}
                />
                <div className="absolute inset-0 my-[28%] mx-[13%] w-[24%] h-[6%] z-[3] bg-black bg-cover bg-center text-white flex items-center justify-center">
                  <span className="">{currentImage && currentImage[1]}</span>
                </div>
                <div
                  className="absolute inset-0 my-[64.5%] mx-[80%] w-[10%] aspect-square z-[3] bg-[hsl(36,100%,82%)]"
                  ref={rotatingSquare}
                />
              </>
            )}
          </div>
          <div>
            <Link to="render">
              <Button
                className="p-10 w-[20rem] rounded border-white bg-transparent border-[.05rem] "
                icon={<ExportOutlined className="text-white text-3xl" />}
                iconPosition="end"
              >
                <Typography.Text className="text-3xl flex justify-center items-center gap-4">
                  <span className="text-white">Browse</span>
                </Typography.Text>
              </Button>
            </Link>
          </div>
        </ContentWrapper>
      </div>
      <div
        className={cn(
          'w-full bg-cover bg-center flex justify-center flex-col relative',
        )}
        style={{
          backgroundImage: `url("/city.png")`,
          height: 'auto',
        }}
      >
        <div
          className="w-full h-full absolute isolate -z-[0] "
          style={{
            backdropFilter: 'blur(5px)',
            background: 'linear-gradient(210deg, rgba(0,0,0,.5), black)',
          }}
        />
        <ContentWrapper>
          <Flex vertical className="z-0 h-full">
            <Typography.Title style={{ color: 'white' }}>
              3D Assets Store
            </Typography.Title>
            <Flex
              gap={30}
              className={isDesktopOrLaptop ? 'h-[20rem]' : 'h-[50%]'}
              vertical={!isDesktopOrLaptop}
            >
              <div className="bg-cover h-full bg-center aspect-square grid grid-cols-2 rounded gap-3 relative">
                <div
                  className="w-full h-full bg-white rounded bg-cover bg-center"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                >
                  1
                </div>
                <div
                  className="w-full h-full bg-white rounded bg-cover bg-center"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                >
                  1
                </div>
                <div
                  className="w-full h-full bg-white rounded bg-cover bg-center"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                >
                  1
                </div>
                <div
                  className="w-full h-full bg-white rounded bg-cover bg-center"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                >
                  1
                </div>
                <div
                  className="w-[50%] aspect-square inset-0 m-auto bg-white rounded bg-cover bg-center absolute shadow-black shadow-xl"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                >
                  1
                </div>
              </div>
              <Flex className="text-left h-full" vertical>
                <Typography.Paragraph
                  style={{ color: 'white' }}
                  className="text-left mb-1"
                >
                  A personal collection of 3D models, textures, and
                  assets—created with passion for fellow hobbyists. Whether
                  you're into 3D design for fun or as a new adventure, this
                  store offers hand-crafted assets to spark creativity and make
                  your projects shine.
                </Typography.Paragraph>
                <div className="mt-auto flex gap-3">
                  <Typography.Title style={{ color: 'white' }}>
                    0
                  </Typography.Title>
                  <Typography.Text style={{ color: 'white' }}>
                    Assets
                    <br />
                    available
                  </Typography.Text>
                </div>
                <Link to="assets">
                  <Button
                    className="w-[15rem] h-[4rem] bg-transparent text-white"
                    size="large"
                    variant="outlined"
                    icon={<AppstoreOutlined style={{ fontSize: '2rem' }} />}
                  >
                    <Typography.Text
                      style={{ color: 'white', fontSize: '1.5rem' }}
                    >
                      Browse
                    </Typography.Text>
                  </Button>
                </Link>
              </Flex>
            </Flex>
          </Flex>
          <Typography.Title
            level={5}
            style={{ color: 'white' }}
            className="z-0 text-left"
          >
            Catalogs
          </Typography.Title>
          <Flex className="overflow-x-auto gap-5 z-0">
            {Array(5)
              .fill('')
              .map((item) => (
                <div
                  className="bg-cover h-[10rem] bg-center aspect-video rounded"
                  style={{
                    backgroundImage: `url("${databaseURL('website', 'images/hero.png')}")`,
                  }}
                ></div>
              ))}
          </Flex>
        </ContentWrapper>
      </div>
    </div>
  );
}
